//! One-shot helper: derive faucet PubKey address from the dev keypair generated by genkey.
use celenium_addresses::{Address, Prefix, Version};
use secp256k1::{Keypair, Secp256k1};

fn main() {
    // Dev faucet keypair (generated locally; private key stored in /mnt/e/Coding/cenium-keys/faucet-wallet.key)
    let secret_hex = "e2d4e4ae9891a573ca17143ecf100c0b84003f0852d03a9de7b1f72ff8a087e0";
    let mut secret = [0u8; 32];
    for (i, b) in secret_hex.as_bytes().chunks(2).enumerate() {
        secret[i] = u8::from_str_radix(std::str::from_utf8(b).unwrap(), 16).unwrap();
    }
    let secp = Secp256k1::new();
    let keypair = Keypair::from_seckey_slice(&secp, &secret).expect("valid secret");
    let (xonly, _parity) = keypair.x_only_public_key();
    let addr = Address::new(Prefix::Mainnet, Version::PubKey, &xonly.serialize());
    println!("FAUCET_ADDRESS={}", addr);
    println!("FAUCET_PUBKEY={}", hex(&xonly.serialize()));
}

fn hex(bytes: &[u8]) -> String {
    let mut s = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        s.push_str(&format!("{b:02x}"));
    }
    s
}
